/*
 * A073492  Numbers having at least one prime gap in their factorization.
 * https://oeis.org/A073492
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n‑th positive integer that has at least one prime
 *            gap in its factorization (OEIS A073492). The sequence is
 *            generated by testing each integer in order, factorizing with a
 *            simple trial division using a precomputed list of primes, and
 *            checking whether any two consecutive distinct prime f...
 * Range:     u8 n <= 151, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

/* Prime sieve – precompute all primes up to LIMIT once. */
#define PRIMES_LIMIT 2000000UL

static uint64_t *prime_list = NULL;
static size_t prime_count = 0;
static bool primes_built = false;

static void build_prime_list(void)
{
    bool *is_prime = (bool *)calloc(PRIMES_LIMIT + 1, sizeof(bool));
    if (!is_prime) return;            /* unlikely; gives empty list */

    for (uint64_t i = 2; i <= PRIMES_LIMIT; ++i) is_prime[i] = true;

    for (uint64_t i = 2; i * i <= PRIMES_LIMIT; ++i) {
        if (is_prime[i]) {
            for (uint64_t j = i * i; j <= PRIMES_LIMIT; j += i) {
                is_prime[j] = false;
            }
        }
    }

    /* first count primes */
    prime_count = 0;
    for (uint64_t i = 2; i <= PRIMES_LIMIT; ++i) {
        if (is_prime[i]) ++prime_count;
    }

    prime_list = (uint64_t *)malloc(prime_count * sizeof(uint64_t));
    if (!prime_list) {
        prime_count = 0;
        free(is_prime);
        return;
    }

    size_t pos = 0;
    for (uint64_t i = 2; i <= PRIMES_LIMIT; ++i) {
        if (is_prime[i]) prime_list[pos++] = i;
    }

    free(is_prime);
}

/* Binary search for a prime's index in prime_list.
   Returns prime_count if p is not found. */
static size_t prime_index_of(uint64_t p)
{
    size_t lo = 0, hi = prime_count;
    while (lo < hi) {
        size_t mid = (lo + hi) >> 1;
        if (prime_list[mid] < p) lo = mid + 1;
        else if (prime_list[mid] > p) hi = mid;
        else return mid;
    }
    return prime_count;
}

/* Test whether n has at least one prime gap in its factorization. */
static bool has_prime_gap(uint64_t n)
{
    uint64_t temp = n;
    uint64_t distinct_primes[64];  /* enough for 64-bit numbers */
    size_t pc = 0;

    for (size_t i = 0; i < prime_count && prime_list[i] * prime_list[i] <= temp; ++i) {
        uint64_t p = prime_list[i];
        if (temp % p == 0) {
            distinct_primes[pc++] = p;
            while (temp % p == 0) temp /= p;
        }
    }
    if (temp > 1) {
        distinct_primes[pc++] = temp;     /* remaining prime factor */
    }

    if (pc <= 1) return false;        /* need at least two distinct primes */

    for (size_t i = 0; i + 1 < pc; ++i) {
        uint64_t p1 = distinct_primes[i];
        uint64_t p2 = distinct_primes[i + 1];

        size_t idx = prime_index_of(p1);
        if (idx >= prime_count) return true;    /* p1 beyond known primes */
        if (idx + 1 >= prime_count) return true;/* no next prime info */
        if (prime_list[idx + 1] != p2) return true; /* gap detected */
    }
    return false;                     /* all primes are consecutive */
}

/* Memoised cache of the sequence values. */
static seq_t *cache = NULL;
static size_t cache_len = 0;
static size_t cache_cap = 0;
static uint64_t next_candidate = 10;          /* a(1) = 10 */

/* Append a new term to the cache, expanding capacity as needed. */
static void append_term(seq_t val)
{
    if (cache_len == cache_cap) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 8;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp) return;               /* allocation failure – ignore */
        cache = tmp;
        cache_cap = new_cap;
    }
    cache[cache_len++] = val;
}

/*-----------------------------------------------------------------*/
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;        /* undefined for n=0, safe return */

    if (!primes_built) {
        build_prime_list();
        primes_built = true;
    }

    while (cache_len < (size_t)n) {
        if (has_prime_gap(next_candidate)) {
            seq_t val = (seq_t)next_candidate;
            append_term(val);
        }
        ++next_candidate;
    }
    return cache[(size_t)n - 1];
}
